'use strict';

const { Router } = require('express');
const _ = require('lodash');

const DEFAULTS = { currency: 'USD', newsletter: false };

module.exports = function preferencesRouter() {
  const router = Router();
  const saved = new Map();

  router.put('/:customerId', (req, res) => {
    const preferences = _.merge({}, DEFAULTS, req.body);
    saved.set(req.params.customerId, preferences);
    res.json(preferences);
  });

  return router;
};

